let all = $input.all();
// Test Inbound (Task 20): the automated dialog tests POST a channel-native body to the Test-Key webhook wf1-test - a
// Telegram update, or a WhatsApp Trigger item {...change.value, field} (or an array of them). It is unwrapped here, so
// everything below handles it exactly like the real triggers' output. Only the test contact ranges pass: Telegram chat
// 9000000NNN, WhatsApp sender 1555000NNNN (send_message captures replies to them into test_outbox instead of sending).
// Anything else ends the run here - no reply, no owner alert - so the key can never make the bot message a real person.
let isTest = false;
try { isTest = $('Test Inbound').isExecuted === true; } catch (e) { isTest = false; }
if (isTest) {
  const b = all[0] && all[0].json ? all[0].json.body : undefined;
  all = (Array.isArray(b) ? b : [b]).filter((x) => x && typeof x === 'object' && !Array.isArray(x)).map((json) => ({ json }));
  const inRange = (v) => v.message
    ? /^9000000\d{3}$/.test(String(v.message.chat?.id ?? ''))
    : v.field === 'messages' && Array.isArray(v.messages) && v.messages.length > 0
      && v.messages.every((m) => m && typeof m.from === 'string' && /^1555000\d{4}$/.test(m.from));
  if (!all.length || !all.every((it) => inRange(it.json))) return [];
}
// A test run's item carries test: true (Create Client then uses the client_id prefix C-test-); a real item never has the field.
const j = all[0].json;
if (j.message) {  // Telegram update
  const m = j.message;
  // Private chats only: in a group chat.id is the group, not a client, and the bot must not answer there.
  if (!m.chat || m.chat.type !== 'private') return [];
  return [{ json: { channel: 'tg', contact_id: 'tg:' + m.chat.id, text: (m.text || '').trim(), raw_name: [m.from?.first_name, m.from?.last_name].filter(Boolean).join(' '), ...(isTest ? { test: true } : {}) } }];
}
// Meta WhatsApp Cloud API (Task 15). WhatsApp Trigger emits one item per webhook change, shaped { ...change.value, field }
// (messaging_product, metadata, contacts, messages, statuses, field): there is no entry[] level here.
// One run handles ONE sender (everything downstream reads $('Normalize').first()). A Meta batch can hold several
// changes and several messages, so: gather every message of every item, take the sender of the earliest one, join that
// sender's texts in timestamp order, and report everything else as dropped (alert_text, sent to the owner by a side branch).
const IGNORED = ['reaction', 'unsupported', 'system'];  // not something the client said to the bot: no reply, no alert
const msgs = [];
let malformed = 0, seq = 0;
for (const it of all) {
  const v = it.json || {};
  if (v.field !== 'messages' || !Array.isArray(v.messages)) continue;  // statuses, template/account updates, ...
  const contacts = Array.isArray(v.contacts) ? v.contacts : [];
  for (const m of v.messages) {
    if (!m || typeof m !== 'object' || IGNORED.includes(m.type)) continue;
    // Meta gives the number as E.164 digits without a plus. Anything else must not become a contact_id, but must not vanish either.
    const from = typeof m.from === 'string' ? m.from : '';
    if (!/^\d{7,15}$/.test(from)) { malformed++; continue; }
    const c = contacts.find((x) => x && x.wa_id === from) || (contacts.length === 1 ? contacts[0] : null);
    const ts = Number(m.timestamp);
    msgs.push({
      from, seq: seq++, ts: Number.isFinite(ts) ? ts : 0,
      text: m.type === 'text' && typeof m.text?.body === 'string' ? m.text.body.trim() : '',
      name: typeof c?.profile?.name === 'string' ? c.profile.name : '',
    });
  }
}
if (!msgs.length && !malformed) return [];  // only statuses / other fields / reactions: start nothing
msgs.sort((a, b) => a.ts - b.ts || a.seq - b.seq);
const first = msgs[0];
const counts = new Map();
for (const m of msgs) if (m.from !== first?.from) counts.set(m.from, (counts.get(m.from) || 0) + 1);
const dropped_senders = [...counts].map(([f, n]) => ({ contact_id: 'wa:+' + f, count: n }));
const lines = dropped_senders.map((d) => '⚠️ WhatsApp batch: ' + d.count + ' message(s) from ' + d.contact_id + ' were not processed — ask them to resend');
if (malformed) lines.push('⚠️ WhatsApp batch: ' + malformed + ' message(s) with an unreadable sender number were not processed');
const alert_text = lines.join('\n');
if (!first) return [{ json: { channel: 'wa', contact_id: '', text: '', raw_name: '', dropped_senders, alert_text, ...(isTest ? { test: true } : {}) } }];  // alert only: Has Sender? stops the main path
// Non-text (image, sticker, audio, ...) keeps the contact and gives text '': the same Send Non-Text path as a Telegram sticker.
const own = msgs.filter((m) => m.from === first.from);
return [{ json: {
  channel: 'wa', contact_id: 'wa:+' + first.from,
  text: own.map((m) => m.text).filter(Boolean).join('\n'),
  raw_name: (own.find((m) => m.name) || first).name,
  dropped_senders, alert_text, ...(isTest ? { test: true } : {}),
} }];

// Validate first: an empty or malformed contact_id must match NO client row (a comparison with '' would match every row whose column is blank).
const raw = String($('Normalize').first().json.contact_id || '').trim();
const ok = /^(tg:\d{1,20}|wa:\+\d{1,20})$/.test(raw);
const formula = ok
  ? (raw.startsWith('tg:') ? "{telegram_chat_id}='" + raw.slice(3) + "'" : "{phone}='" + raw.slice(3) + "'")
  : "{client_id}='__no_such_client__'";
return [{ json: { formula } }];

// '' when the detection failed (error item, no answer): the client is stored without a language and detected again next time.
const L = ['en','de','es','fr','it','pt','ru','uk','pl','tr','nl','ar','he','zh','ja'];
const j = $input.first().json || {};
const a = String(j.text || j.output || '').trim().toLowerCase().slice(0, 2);
return [{ json: { language: !a || j.error ? '' : (L.includes(a) ? a : 'en') } }];

const n = $('Normalize').first().json;
const ran = name => { try { return $(name).isExecuted === true; } catch (e) { return false; } };
let rec = $('Client').first().json || {};
if (ran('Create Client')) rec = $('Create Client').first().json || {};
else if (ran('Update Language')) { const u = $('Update Language').first().json || {}; if (u.id && u.fields) rec = u; }
const f = rec.fields || {};
if (!rec.id || !f.client_id) throw new Error('wf1-inbound: no Clients row with a client_id for ' + n.contact_id);
const detected = ran('Language') ? String($('Language').first().json.language || '') : '';
return [{ json: {
  client_rec: rec.id, client_id: String(f.client_id), client_name: f.name || '', language: f.language || detected || 'en',
  client_status: f.status || 'new', last_agent_reply_at: f.last_agent_reply_at || '',
  contact_id: n.contact_id, channel: n.channel, text: n.text
} }];

const YES = ['yes','yeah','yep','yup','ok','okay','sure','confirm','confirmed','correct','right','да','ага','подтверждаю','ок','давай','хорошо','верно','ja','jawohl','genau','passt','bestätige','bestätigen','sí','si','vale','claro','confirmo','correcto','oui','d\'accord','je confirme','exact','va bene','confermo','sim','так','добре','підтверджую','evet','tamam','onaylıyorum','tak','potwierdzam','oké','prima','نعم','تمام','כן','是','好','确认','はい'];
const NO = ['no','nope','cancel','not now','нет','отмена','не надо','отмени','nein','nee','abbrechen','stornieren','cancelar','cancela','non','annuler','annulla','não','nao','ні','скасувати','hayır','iptal','nie','anuluj','annuleren','لا','לא','不','取消','いいえ'];
const j = $input.first().json;
const raw = (j.text || '').toLowerCase().replace(/[\u2018\u2019\u02bc]/g, "'");
// \b is ASCII-only in JS, so the boundaries are written out: no letter, digit or apostrophe on either side.
const norm = raw.replace(/[^\p{L}\p{N}\s']/gu, ' ').replace(/\s+/g, ' ').trim()
  .replace(/(?<![\p{L}\p{N}'])(please|пожалуйста|bitte|por favor|s'il vous plaît)(?![\p{L}\p{N}'])/gu, '').replace(/\s+/g, ' ').trim();
const words = norm ? norm.split(' ') : [];
const is_short = words.length > 0 && words.length <= 3;
let kind = 'other';
if (is_short && YES.includes(norm)) kind = 'yes';
else if (is_short && NO.includes(norm)) kind = 'no';
return [{ json: { ...j, kind, is_short } }];

// Which bot question does a short reply answer? Only the LAST one: a YES must never cancel a visit the bot did not just ask about.
// A cancel question is the last one when it was asked at or after the client's last agent reply (WF-1 writes cancel_asked_at =
// exactly the last_agent_reply_at it just wrote; any later agent reply is later) and no reminder went out after it.
const c = $('Classify').first().json;
const cd = $('Client Data').first().json;
const ms = (v) => { const t = Date.parse(String(v || '')); return Number.isFinite(t) ? t : NaN; };
const rows = $('Pending').all().map(i => (i.json || {}).fields || {}).filter(f => f.appt_id);
const pending = rows.find(f => f.status === 'pending') || {};
const last = ms(cd.last_agent_reply_at);
const sent = rows.map(f => ms(f.reminder_sent_at)).filter(Number.isFinite);
const lastReminder = sent.length ? Math.max(...sent) : -Infinity;
const ask = rows.filter(f => ['booked', 'reminded', 'confirmed'].includes(f.status) && Number.isFinite(last) && ms(f.cancel_asked_at) >= last && !(lastReminder > ms(f.cancel_asked_at)))
  .sort((a, b) => ms(b.cancel_asked_at) - ms(a.cancel_asked_at))[0];
let route = 'agent', yes_target = '', cancel_appt_id = '';
if (ask) {
  // The cancel question is the bot's last message. YES (a known word, or a short phrase Haiku reads as YES) cancels that visit
  // while the request is unexpired; NO, anything else or an expired request goes to the agent and the visit stays booked.
  const fresh = ms(ask.cancel_expires_at) > Date.now();
  if (fresh && c.kind === 'yes') { route = 'cancel'; cancel_appt_id = ask.appt_id; }
  else if (fresh && c.kind === 'other' && c.is_short) { route = 'llm'; yes_target = 'cancel'; cancel_appt_id = ask.appt_id; }
} else if (c.kind === 'yes' && pending.appt_id) route = 'confirm';
else if (c.kind === 'other' && c.is_short && pending.appt_id) { route = 'llm'; yes_target = 'confirm'; }
else if (c.kind === 'yes' || c.kind === 'no') route = 'reminder';
return [{ json: { route, yes_target, cancel_appt_id } }];

const kind = $('Classify').first().json.kind;
const last = String($('Client Data').first().json.last_agent_reply_at || '').trim();
const rows = $input.all().map(i => (i.json || {}).fields || {}).filter(f => f.appt_id);
let answer = false;
if (['yes', 'no'].includes(kind) && rows.length) {
  if (!last) answer = true;
  else {
    const l = DateTime.fromISO(last);
    const sent = rows.map(f => DateTime.fromISO(String(f.reminder_sent_at || ''))).filter(d => d.isValid).map(d => d.toMillis());
    answer = l.isValid && sent.length > 0 && Math.max(...sent) > l.toMillis();
  }
}
return [{ json: { answer, reminded: rows.length } }];
